result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ward_engine.py", "content": """"Ward bed-allocation engine with hard constraints (educational synthetic hospital).

Wards
-----
W1 : 4 beds in 2 two-bed bays          (bays W1-BAY-A, W1-BAY-B)
W2 : 3 single rooms                    (W2-SINGLE-1..3)
W3 : 4 beds in one bay                 (bay W3-BAY, "far ward")

Hard constraints
----------------
1. A two-bed bay NEVER mixes sexes.
2. A patient flagged ``needs_isolation`` must get a single room (W2) or an
   EMPTY bay, which is then implicitly locked to them: no other patient may
   be placed in any bed of that bay until they are discharged.
3. A patient flagged ``fall_risk`` can never be placed in W3 (far ward).

API
---
``admit(patient)``    -> Placement (with bed) or WaitlistEntry
``discharge(patient_id)``
plus full queryable state: placements, waitlist, bed occupancy, and an
independent ``invariant_violations()`` checker.

Waitlist policy (documented deliberately): strict head-of-line FIFO. When a
bed frees, the patient at the FRONT of the queue is promoted iff a suitable
bed exists for them; otherwise nobody is promoted (no queue-jumping). This
makes promotion order unambiguously FIFO.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional


# --------------------------------------------------------------------------- #
# Domain objects
# --------------------------------------------------------------------------- #

@dataclass
class Patient:
    id: str
    sex: str  # "M" or "F"
    needs_isolation: bool = False
    fall_risk: bool = False


@dataclass
class Bed:
    id: str
    ward_id: str           # "W1" | "W2" | "W3"
    bay: Optional[str]     # None => private single room
    occupant: Optional[str] = None  # patient id


@dataclass
class Placement:
    patient_id: str
    bed_id: str
    ward_id: str


@dataclass
class WaitlistEntry:
    patient_id: str
    reason: str
    position: int = field(default=0)  # filled in by the engine


FAR_WARD = "W3"


def _default_beds() -> list[Bed]:
    beds: list[Bed] = []
    for bay in ("W1-BAY-A", "W1-BAY-B"):
        for slot in (1, 2):
            beds.append(Bed(id=f"{bay}#{slot}", ward_id="W1", bay=bay))
    for n in (1, 2, 3):
        beds.append(Bed(id=f"W2-SINGLE-{n}", ward_id="W2", bay=None))
    for slot in (1, 2, 3, 4):
        beds.append(Bed(id=f"W3-BAY#{slot}", ward_id=FAR_WARD, bay="W3-BAY"))
    return beds


# --------------------------------------------------------------------------- #
# Engine
# --------------------------------------------------------------------------- #

class Hospital:
    def __init__(self) -> None:
        self.beds: list[Bed] = _default_beds()
        self.beds_by_id: dict[str, Bed] = {b.id: b for b in self.beds}
        self.patients: dict[str, Patient] = {}
        self.placements: dict[str, Placement] = {}
        self.waitlist: list[WaitlistEntry] = []

    # ------------------------- constraint evaluation ---------------------- #

    def check_eligibility(self, patient: Patient, bed: Bed) -> tuple[bool, Optional[str]]:
        """Return (ok, rejection_reason) for placing *patient* in *bed*."""
        if bed.occupant is not None:
            return False, "bed_occupied"
        if patient.fall_risk and bed.ward_id == FAR_WARD:
            return False, "fall_risk_cannot_go_to_far_ward"

        if bed.bay is None:  # single room: always acceptable for anyone
            return True, None

        occupants = [
            self.patients[b.occupant]
            for b in self.beds
            if b.bay == bed.bay and b.occupant is not None
        ]
        if occupants:
            if patient.needs_isolation:
                return False, "isolation_needs_single_room_or_empty_bay"
            if any(o.needs_isolation for o in occupants):
                return False, "bay_locked_for_isolation_patient"
            if any(o.sex != patient.sex for o in occupants):
                return False, "bay_would_mix_sexes"
        # Empty bay is fine for anybody (an isolation patient here locks it).
        return True, None

    def is_bed_available(self, bed_id: str, patient: Patient) -> bool:
        """Public query: could *patient* legally occupy *bed_id* right now?"""
        ok, _ = self.check_eligibility(patient, self.beds_by_id[bed_id])
        return ok

    def _find_bed(self, patient: Patient) -> Optional[Bed]:
        # Preference 1: beds in bays that already hold compatible occupants
        # (fills partially-used bays before opening new ones).
        # Preference 2: remaining beds in stable registration order.
        fallback: list[Bed] = []
        for bed in self.beds:
            ok, _ = self.check_eligibility(patient, bed)
            if not ok:
                continue
            if bed.bay is not None and any(
                b.bay == bed.bay and b.occupant is not None for b in self.beds
            ):
                return bed
            fallback.append(bed)
        return fallback[0] if fallback else None

    # ------------------------------- API ---------------------------------- #

    def admit(self, patient: Patient) -> Placement | WaitlistEntry:
        if patient.id in self.patients:
            raise ValueError(f"patient {patient.id!r} already admitted")
        self.patients[patient.id] = patient
        bed = self._find_bed(patient)
        if bed is None:
            entry = WaitlistEntry(
                patient_id=patient.id,
                reason="no_suitable_bed_available",
                position=len(self.waitlist),
            )
            self.waitlist.append(entry)
            return entry
        return self._assign(patient, bed)

    def discharge(self, patient_id: str) -> None:
        if patient_id in self.placements:
            bed = self.beds_by_id[self.placements.pop(patient_id).bed_id]
            bed.occupant = None
        elif any(e.patient_id == patient_id for e in self.waitlist):
            self.waitlist = [e for e in self.waitlist if e.patient_id != patient_id]
            self._renumber_waitlist()
        else:
            raise KeyError(f"unknown patient {patient_id!r}")
        del self.patients[patient_id]
        self._promote_from_waitlist()

    # ---------------------------- internals -------------------------------- #

    def _assign(self, patient: Patient, bed: Bed) -> Placement:
        assert bed.occupant is None
        bed.occupant = patient.id
        placement = Placement(patient.id, bed.id, bed.ward_id)
        self.placements[patient.id] = placement
        return placement

    def _renumber_waitlist(self) -> None:
        for i, entry in enumerate(self.waitlist):
            entry.position = i

    def _promote_from_waitlist(self) -> None:
        """Strict FIFO: only the head of the queue may be promoted."""
        while self.waitlist:
            head = self.waitlist[0]
            patient = self.patients.get(head.patient_id)
            if patient is None:  # defensive; shouldn't happen
                self.waitlist.pop(0)
                continue
            bed = self._find_bed(patient)
            if bed is None:
                break  # head-of-line blocks; nobody jumps the queue
            self.waitlist.pop(0)
            self._renumber_waitlist()
            self._assign(patient, bed)

    # --------------------------- state queries ----------------------------- #

    def get_placement(self, patient_id: str) -> Optional[Placement]:
        return self.placements.get(patient_id)

    def get_waitlist(self) -> list[WaitlistEntry]:
        return list(self.waitlist)

    def bed_occupant(self, bed_id: str) -> Optional[str]:
        return self.beds_by_id[bed_id].occupant

    def bay_occupants(self, bay: str) -> list[str]:
        return [b.occupant for b in self.beds if b.bay == bay and b.occupant]

    def ward_occupancy(self) -> dict[str, int]:
        occ = {"W1": 0, "W2": 0, "W3": 0}
        for p in self.placements.values():
            occ[p.ward_id] += 1
        return occ

    # -------------------------- invariant checker -------------------------- #

    def invariant_violations(self) -> list[str]:
        """Independent audit of every hard constraint + bookkeeping consistency."""
        problems: list[str] = []

        # 1. no double-occupied bed (occupant field holds at most one id by
        #    construction, but verify placements agree with beds).
        seen: dict[str, str] = {}  # bed_id -> patient_id
        for pid, pl in self.placements.items():
            if pl.bed_id in seen:
                problems.append(
                    f"double_occupancy: {seen[pl.bed_id]} and {pid} both in {pl.bed_id}"
                )
            seen[pl.bed_id] = pid
            bed = self.beds_by_id.get(pl.bed_id)
            if bed is None:
                problems.append(f"phantom_bed: {pid} placed in unknown {pl.bed_id}")
            elif bed.occupant != pid:
                problems.append(
                    f"bookkeeping_mismatch: {pid} mapped to {pl.bed_id} "
                    f"but bed holds {bed.occupant}"
                )

        for bed in self.beds:
            if bed.occupant is not None and bed.occupant not in self.placements:
                problems.append(f"orphan_occupant: {bed.id} holds unknown {bed.occupant}")

        # 2. per-bay checks: no mixed sexes, no isolation cohabitants,
        #    no double occupancy within a bay.
        bays: dict[str, list[Bed]] = {}
        for bed in self.beds:
            if bed.bay is not None:
                bays.setdefault(bed.bay, []).append(bed)

        for bay, bay_beds in bays.items():
            occupants = [b.occupant for b in bay_beds if b.occupant is not None]
            if len(occupants) != len(set(occupants)):
                problems.append(f"double_occupied_bed_in_bay: {bay}")
            patients = [self.patients[o] for o in occupants if o in self.patients]
            sexes = {p.sex for p in patients}
            if len(sexes) > 1:
                problems.append(f"mixed_sex_bay: {bay} holds sexes {sorted(sexes)}")
            isolated = [p for p in patients if p.needs_isolation]
            if isolated and len(patients) > 1:
                problems.append(
                    f"isolation_cohabitation: {bay} shares with "
                    f"{[p.id for p in patients]}"
                )

        # 3. fall-risk never in far ward.
        for pid, pl in self.placements.items():
            p = self.patients.get(pid)
            if p and p.fall_risk and pl.ward_id == FAR_WARD:
                problems.append(f"fall_risk_in_far_ward: {pid} in {pl.bed_id}")

        # 4. waitlisted patients must not secretly hold beds.
        placed_ids = set(self.placements)
        for entry in self.waitlist:
            if entry.patient_id in placed_ids:
                problems.append(f"waitlist_ghost: {entry.patient_id} waitlisted yet placed")

        return problems
